    48	        this.order = order;
    49	        this.sale = null; // 서로 배타적 관계
    50	    }
    51	
    52	    public void assignSale(Sale sale) {
    53	        this.sale = sale;
    54	        this.order = null; // 서로 배타적 관계
    55	    }
